#include "acl/acl_internal.h"
#include "uid/uid.h"
#include "rem_file/rem_file.h"

/* AST_$GET_ACL_ATTRIBUTES flags (`move.w #0x1,-(SP)` 0x00E47BF4) */
#define ACL_IMAGE_ATTR_FLAGS    1

/* attr.obj_flags[1]: the object must be an ACL (`cmpi.w #0x3` 0x00E47C1A) */
#define ACL_IMAGE_OBJ_TYPE_ACL  3

/* The default image's length and version (0x00E47D64, 0x00E47DB4) */
#define ACL_IMAGE_DEFAULT_LEN   0x34
#define ACL_IMAGE_VERSION       5

/* A uid whose top word is 2 is a directory's ACL (`cmpi.w #0x2` 0x00E47D78) */
#define ACL_IMAGE_DIR_UID_TYPE  2

/* Image layout: entries of 0x20 bytes from +0x34, count at +0x0E
 * (acl_$cache_slot_t.entry_count; 0x00E47CD8-0x00E47CDE,
 * 0x00E47D26-0x00E47D38) */
#define ACL_IMAGE_ENTRY_BASE    0x34
#define ACL_IMAGE_ENTRY_SIZE    0x20
#define ACL_IMAGE_ENTRY_FLAGS   0x1B

void acl_$image_internal(uid_t *source_uid, int16_t buffer_len, int8_t flag,
                         void *image_out, int16_t *len_out,
                         acl_$prot_data_t *data_out, int8_t *flag_out,
                         status_$t *status)
{
    uid_t            uid;           /* (-0x80,A6) */
    uid_t            uid2;          /* (-0x78,A6) */
    uid_t            uid3;          /* (-0x70,A6) */
    ast_$acl_attr_t  attr;          /* (-0x68,A6) */
    file_$obj_loc_t  loc;           /* (-0x30,A6) */
    uid_t            def_uid;       /* (-0x10,A6) */
    status_$t        st;            /* (-0x94,A6) */
    int16_t          slot;          /* D0w */
    int16_t          len;           /* D1w */
    int16_t          n;
    uint8_t         *img = (uint8_t *)image_out;

    /* 0x00E47B98-0x00E47BB2 */
    uid = *source_uid;
    uid.low &= ~0x01000000u;                    /* bclr.b #0x0,(-0x7c,A6) */
    uid2 = uid;

    /* 0x00E47BB6-0x00E47BD4 */
    if (!(uid.high == ACL_$NIL.high && uid.low == ACL_$NIL.low) &&
        ((uid.high >> 24) & 0xFF) != 0) {
        /* 0x00E47BD8-0x00E47C10 */
        loc.uid = uid;
        loc.flags &= ~0x40;                     /* bclr.b #0x6,(-0x13,A6) */
        AST_$GET_ACL_ATTRIBUTES(&loc, ACL_IMAGE_ATTR_FLAGS, &attr, &st);
        if (st != status_$ok) {
            *status = st;
            return;
        }
        /* 0x00E47C14-0x00E47C28 */
        if (attr.obj_flags[1] != ACL_IMAGE_OBJ_TYPE_ACL) {
            *status = status_$acl_wrong_type;
            return;
        }
        /* 0x00E47C2C-0x00E47C70 */
        if ((attr.obj_flags[3] & 0x01) == 0 && loc.flags < 0) {
            REM_FILE_$ACL_IMAGE(&loc.loc_info, &uid, (uint8_t)flag, image_out,
                                (uint16_t *)len_out, data_out, status);
            if ((int16_t)((acl_$image_t *)image_out)->version <
                ACL_IMAGE_VERSION) {                    /* 0x00E47C5E bge */
                *flag_out = (int8_t)0xFF;
            } else {
                *flag_out = 0;
            }
            return;
        }
    }

    /* 0x00E47C74-0x00E47CB2 */
    if (!(uid.high == UID_$NIL.high && uid.low == UID_$NIL.low)) {
        slot = acl_$find_acl_slot(&uid, flag_out, data_out, &st);
    } else {
        ACL_$DEF_ACLDATA(data_out, &def_uid);
        st = status_$ok;
        slot = ACL_CACHE_NO_SLOT;               /* moveq #-0x1,D0 */
        *flag_out = 0;
    }

    if (((uint32_t)st & 0xFFFFu) != 0) {        /* tst.w (-0x92,A6) */
        *len_out = 0;                           /* 0x00E47DE2 */
    } else if (slot != ACL_CACHE_NO_SLOT) {
        /* 0x00E47CC4-0x00E47D0A */
        acl_$cache_slot_t *cs = &ACL_$DATA.acl_cache[slot];
        len = (int16_t)((cs->entry_count << 5) + ACL_IMAGE_DEFAULT_LEN);
        *len_out = len;
        if (len > buffer_len) {
            st = status_$image_buffer_too_small;
        } else {
            const uint32_t *src = (const uint32_t *)(const void *)cs;
            uint32_t *dst = (uint32_t *)image_out;
            n = (int16_t)(len / 4 - 1);         /* addq #3 / asr #2 / subq #1 */
            if (n >= 0) {
                do {
                    *dst++ = *src++;
                } while (--n != -1);            /* dbf */
            }
        }

        /* 0x00E47D0C-0x00E47D5E */
        if ((int8_t)(~flag & *flag_out) < 0) {
            uint8_t *e = img + ACL_IMAGE_ENTRY_BASE;
            n = (int16_t)((int16_t)((acl_$cache_slot_t *)image_out)->entry_count
                          - 1);         /* move.w (0xe,A2) / subq.w #1 */
            if (n >= 0) {
                do {
                    e[ACL_IMAGE_ENTRY_FLAGS] &= ~0x40;
                    e += ACL_IMAGE_ENTRY_SIZE;
                } while (--n != -1);
            }
            data_out->owner_rights  &= ~0x40;
            data_out->group_rights  &= ~0x40;
            data_out->org_rights    &= ~0x40;
            data_out->world_rights  &= ~0x40;
            data_out->subsys_rights &= ~0x40;
        }
    } else {
        /* 0x00E47D62-0x00E47DE0: the default image */
        acl_$image_t *im = (acl_$image_t *)image_out;
        int i;

        *len_out = ACL_IMAGE_DEFAULT_LEN;
        uid3 = uid2;
        if (((uid3.high >> 16) & 0xFFFF) == ACL_IMAGE_DIR_UID_TYPE) {
            im->acl_uid = ACL_$DIR_ACL;
        } else {
            im->acl_uid = ACL_$FILE_ACL;
        }
        im->reserved_0e = 0;
        im->subsys_uid = UID_$NIL;
        im->initial_acl_uid = im->acl_uid;
        im->version = ACL_IMAGE_VERSION;
        for (i = 0; i < 12; i++) {              /* moveq #0xb / dbf */
            im->rights[i] = 0;
        }
        im->reserved_0a = 0;
        im->reserved_10 = 0;
        im->reserved_22 = 0;
        im->reserved_26 = 0;
        im->reserved_28 = 0;
        im->reserved_29 = 0;
    }

    /* 0x00E47DE6-0x00E47DE8 */
    *status = st;
}
